-- =============================================================================
-- بيانات تجريبية للتطوير والاختبار فقط (dev_seed). لا تُشغَّل على قاعدة الإنتاج أبداً.
-- يُشغَّل على قاعدة فارغة بعد schema_v5.sql والترحيلات (backend\setup-db.bat يفعل ذلك).
-- يرفض العمل إذا كانت القاعدة فيها مستخدمون أصلاً، أو اسمها alrahma_db أو يحتوي prod.
-- كلمة المرور لكل حسابات الموظفين: Rahma-Dev-2026 (Argon2id). المراجع يدخل برقم الهاتف ورمز OTP
-- (يظهر في مربع Sandbox في تطبيق المراجع في بيئة التطوير). الحسابات موثّقة في dock/docs/handoff/accounts.md
-- =============================================================================
\set ON_ERROR_STOP on
BEGIN;

DO $$
BEGIN
    IF current_database() = 'alrahma_db' OR current_database() ILIKE '%prod%' THEN
        RAISE EXCEPTION 'dev_seed: refused on database % (production)', current_database();
    END IF;
    IF EXISTS (SELECT 1 FROM users) THEN
        RAISE EXCEPTION 'dev_seed: database % already has users; run it on an empty database only', current_database();
    END IF;
END $$;

-- ------------------------------------------------------------------ الفروع (بموقعين على الخريطة)

-- السبت إلى الخميس 08:00-22:00، والجمعة مغلق (weekday: 0 = الأحد ... 6 = السبت)
SELECT b, d, 1, '08:00', '22:00' FROM unnest(ARRAY['00000000-0000-7000-8000-000000000b01', '00000000-0000-7000-8000-000000000b02']::uuid[]) b,
       unnest(ARRAY[0, 1, 2, 3, 4, 6]) d;
UPDATE branches SET working_hours = 'السبت - الخميس: 08:00-22:00، الجمعة: مغلق';

-- ------------------------------------------------------------------ العيادات والأقسام

-- ------------------------------------------------------------------ أدوار مخصصة للحسابات التجريبية

-- ------------------------------------------------------------------ الحسابات (كلمة المرور: Rahma-Dev-2026)

SELECT u, '00000000-0000-7000-8000-000000000b01'::uuid FROM unnest(ARRAY[
  '00000000-0000-7000-8000-00000000a001', '00000000-0000-7000-8000-00000000a002', '00000000-0000-7000-8000-00000000a003',
  '00000000-0000-7000-8000-00000000a004', '00000000-0000-7000-8000-00000000a005', '00000000-0000-7000-8000-00000000a006',
  '00000000-0000-7000-8000-00000000a007', '00000000-0000-7000-8000-00000000a008', '00000000-0000-7000-8000-00000000a009']::uuid[]) u;

-- ------------------------------------------------------------------ الأطباء

-- ------------------------------------------------------------------ الخدمات والأسعار (بالدينار)
-- الأدوية (كتالوج الصيدلية): السعر بالدينار، وبعضها لا يُصرف للمراجع الخارجي إلا بوصفة
SELECT b, c, n, 'pharmacy', p, r FROM (VALUES
 ('00000000-0000-7000-8000-000000000b01'::uuid, '00000000-0000-7000-8000-0000000c0105'::uuid, 'باراسيتامول 500 ملغ (شريط)', 1500, FALSE),
 ('00000000-0000-7000-8000-000000000b01', '00000000-0000-7000-8000-0000000c0105', 'أموكسيسيلين 500 ملغ (علبة)', 6000, TRUE),
 ('00000000-0000-7000-8000-000000000b01', '00000000-0000-7000-8000-0000000c0105', 'أوميبرازول 20 ملغ (علبة)', 5000, FALSE),
 ('00000000-0000-7000-8000-000000000b01', '00000000-0000-7000-8000-0000000c0105', 'شراب سعال للأطفال', 4000, FALSE),
 ('00000000-0000-7000-8000-000000000b01', '00000000-0000-7000-8000-0000000c0105', 'إنسولين (قلم)', 25000, TRUE),
 ('00000000-0000-7000-8000-000000000b02', '00000000-0000-7000-8000-0000000c0203', 'باراسيتامول 500 ملغ (شريط)', 1500, FALSE),
 ('00000000-0000-7000-8000-000000000b02', '00000000-0000-7000-8000-0000000c0203', 'كريم هيدروكورتيزون', 7000, TRUE)
) v(b, c, n, p, r);

-- سعر صرف الدولار لليوم (دينار لكل دولار) لكل فرع

-- ------------------------------------------------------------------ المراجعون وحساب تطبيق المراجع

-- ------------------------------------------------------------------ وجبات الأطباء (أمس، اليوم، غداً) والحجوزات بحالات مختلفة
SELECT ('00000000-0000-7000-8000-00005' || d.n || lpad(o::text, 3, '0'))::uuid, d.doc, d.br, d.cl,
       (now() AT TIME ZONE 'Asia/Baghdad')::date + o - 1, '16:00', '21:00', d.slot, 20, 12
FROM (VALUES ('0001', '00000000-0000-7000-8000-0000000d0001'::uuid, '00000000-0000-7000-8000-000000000b01'::uuid, '00000000-0000-7000-8000-0000000c0101'::uuid, 10),
             ('0002', '00000000-0000-7000-8000-0000000d0002', '00000000-0000-7000-8000-000000000b01', '00000000-0000-7000-8000-0000000c0102', 15),
             ('0003', '00000000-0000-7000-8000-0000000d0003', '00000000-0000-7000-8000-000000000b02', '00000000-0000-7000-8000-0000000c0201', 10)) d(n, doc, br, cl, slot),
     generate_series(0, 2) o;
-- session_id: ...00005<doctor><000|001|002> = أمس / اليوم / غداً

 -- أمس: مكتمل، غياب، ملغى
 ('00000000-0000-7000-8000-0000000b0001', '00000000-0000-7000-8000-0000000e0001', '00000000-0000-7000-8000-000050001000', 1, 'new_visit', 25000, 'online', 'completed', 'paid', '00000000-0000-7000-8000-0000000f0001', NULL, NULL, NULL, FALSE),
 ('00000000-0000-7000-8000-0000000b0002', '00000000-0000-7000-8000-0000000e0004', '00000000-0000-7000-8000-000050001000', 2, 'new_visit', 25000, 'phone', 'no_show', 'unpaid', NULL, NULL, NULL, NULL, TRUE),
 ('00000000-0000-7000-8000-0000000b0003', '00000000-0000-7000-8000-0000000e0003', '00000000-0000-7000-8000-000050002000', 1, 'new_visit', 20000, 'phone', 'cancelled', 'unpaid', NULL, 'ظرف طارئ', now() - interval '1 day', 'patient', FALSE),
 -- اليوم: محجوز (إلكتروني وهاتفي)
 ('00000000-0000-7000-8000-0000000b0004', '00000000-0000-7000-8000-0000000e0002', '00000000-0000-7000-8000-000050002001', 1, 'new_visit', 20000, 'online', 'booked', 'unpaid', '00000000-0000-7000-8000-0000000f0001', NULL, NULL, NULL, FALSE),
 ('00000000-0000-7000-8000-0000000b0005', '00000000-0000-7000-8000-0000000e0003', '00000000-0000-7000-8000-000050001001', 1, 'new_visit', 25000, 'phone', 'booked', 'unpaid', NULL, NULL, NULL, NULL, FALSE),
 ('00000000-0000-7000-8000-0000000b0006', '00000000-0000-7000-8000-0000000e0005', '00000000-0000-7000-8000-000050003001', 1, 'new_visit', 30000, 'phone', 'booked', 'unpaid', NULL, NULL, NULL, NULL, FALSE),
 -- غداً: محجوز إلكترونياً
 ('00000000-0000-7000-8000-0000000b0007', '00000000-0000-7000-8000-0000000e0001', '00000000-0000-7000-8000-000050001002', 1, 'follow_up', 15000, 'online', 'booked', 'unpaid', '00000000-0000-7000-8000-0000000f0001', NULL, NULL, NULL, FALSE),
 ('00000000-0000-7000-8000-0000000b0008', '00000000-0000-7000-8000-0000000e0006', '00000000-0000-7000-8000-000050003002', 1, 'new_visit', 30000, 'phone', 'booked', 'unpaid', NULL, NULL, NULL, NULL, FALSE);
UPDATE patients SET no_show_count = 1 WHERE patient_id = '00000000-0000-7000-8000-0000000e0004';

COMMIT;
